svg.script:
const lang = new URLSearchParams(location.search).get('lang') === 'zh' ? 'zh' : 'en'; document.documentElement.lang = lang === 'zh' ? 'zh-CN' : 'en';
const header = lang === 'zh' ? { title: '即使不用 AI，也完整可用的城市。', subtitle: 'A CITY YOU CAN USE WITHOUT AI.', principle: 'AI 可选，人本城市通达必须持续', principleSub: 'AI OPTIONAL; HUMAN ACCESS CONTINUES', limit: '概念通达关系 / 非测绘 / 非无障碍合规证明', limitSub: 'CONCEPT ACCESS / NOT SURVEYED / NOT COMPLIANCE' } : { title: 'A CITY YOU CAN USE WITHOUT AI.', subtitle: '即使不用 AI，也完整可用的城市。', principle: 'AI OPTIONAL; HUMAN ACCESS CONTINUES', principleSub: 'AI 可选，人本城市通达必须持续', limit: 'CONCEPT ACCESS / NOT SURVEYED / NOT COMPLIANCE', limitSub: '概念通达关系 / 非测绘 / 非无障碍合规证明' };
const mainTitle = document.getElementById('main-title'); mainTitle.textContent = header.title; mainTitle.setAttribute('font-size', lang === 'zh' ? '72' : '58'); document.getElementById('main-subtitle').textContent = header.subtitle; document.getElementById('principle-title').textContent = header.principle; document.getElementById('principle-title').setAttribute('font-size', lang === 'zh' ? '27' : '22'); document.getElementById('principle-subtitle').textContent = header.principleSub; document.getElementById('limit-title').textContent = header.limit; document.getElementById('limit-subtitle').textContent = header.limitSub;
const zh = new Map(Object.entries({ 'JZOI 90 / FIG-06 / ACCESS EQUIVALENCE': 'JZOI 90 / FIG-06 / 通达等价', 'CIVIC PROTOCOL MODERNISM': '公共协议现代主义', 'HERITAGE / SHADE / SLOW MOBILITY': '遗产连续 / 遮荫 / 慢行', 'RAINWATER / REST / PUBLIC-SPACE CONTINUITY': '雨洪缓冲 / 休息 / 公共空间连续', 'E-W STITCH / WALK + CYCLE': '东西缝合 / 步行 + 骑行', 'PUBLIC ARRIVAL / WALK + CYCLE': '公共到达 / 步行 + 骑行', 'INTERFACE ROOM': '接口空间', 'ZZY / FIELD · PUBLIC BYPASS + OBSERVATION': 'ZZY / 场地 · 公共绕行 + 观察边界', 'ORG / COURTYARD NETWORK · POROUS PASSAGES': 'ORG / 院落网络 · 多孔通道', 'DZS / CIVIC ROOM · PUBLIC ARRIVAL + REVIEW': 'DZS / 公共客厅 · 公共到达 + 复核', 'STATIC SIGN + HELP': '固定导视 + 帮助', 'STAFFED DESK': '人工服务台', 'PAPER / OFFLINE': '纸质 / 离线', 'EXPLANATION': '人工解释', 'PHONE HELP': '电话帮助', 'APPEAL': '申诉', 'REVIEW': '人工复核', 'SAME CIVIC': '同等公共', 'OUTCOME': '结果', 'NOT IDENTICAL EXPERIENCE': '等价通达 / 体验可不同', 'ACCESS EQUIVALENCE FIELD / CONCEPT RELATIONSHIPS ONLY': '通达等价场 / 仅表达概念关系', 'STEP-FREE / TACTILE / SHADE / REST LOGIC IS CONCEPTUAL; NO SURVEYED SLOPE, DIMENSION OR OFFICIAL COMPLIANCE CLAIM.': '无台阶 / 触觉导向 / 遮荫 / 休息均为概念逻辑；不主张实测坡度、尺寸或正式合规。', 'THREE COORDINATED SYSTEMS': '三个协同系统', 'A / PUBLIC ACCESS NETWORK': 'A / 公共通达网络', 'WALK · CYCLE · PUBLIC / TRANSIT ARRIVAL': '步行 · 骑行 · 公共 / 公交通达', 'PUBLIC SEQUENCE · E-W STITCHES · BYPASS': '公共序列 · 东西缝合 · 公共绕行', 'B / HUMAN-EQUIVALENT ACCESS': 'B / 人工等价通达', 'SERVICE NODE CONTINUITY · NOT A SECOND ROAD': '服务节点连续 · 不是第二条道路', 'STATIC · STAFFED · PAPER · PHONE · EXPLAIN · APPEAL · REVIEW': '固定导视 · 人工 · 纸质 · 电话 · 解释 · 申诉 · 复核', 'C / BLUE-GREEN + HERITAGE': 'C / 蓝绿 + 遗产系统', 'SLOW MOBILITY · SHADE · REST · RAINWATER': '慢行 · 遮荫 · 休息 · 雨洪调蓄', 'ECOLOGY · HERITAGE · PUBLIC SPACE · BUFFER': '生态 · 遗产 · 公共空间 · 缓冲', 'LOW-TECH CIVIC INFRASTRUCTURE': '低技术公共基础设施', 'ENDPOINT ACCESS': '三端点通达', 'ZZY / FIELD': 'ZZY / 场地', 'PUBLIC BYPASS · OBSERVATION EDGE · HUMAN REVIEW': '公共绕行 · 观察边界 · 人工复核', 'ORG / COURTYARD NETWORK': 'ORG / 院落网络', 'POROUS PASSAGES · OPEN GROUND FLOOR · HUMAN DESK': '多孔通道 · 开放首层 · 人工服务台', 'DZS / CIVIC ROOM': 'DZS / 公共客厅', 'PUBLIC ARRIVAL · APPEAL / REVIEW · CIVIC DECISION ACCESS': '公共到达 · 申诉 / 复核 · 公共决策通达', 'ACCESSIBILITY / CONCEPT LOGIC': '无障碍 / 概念逻辑', 'A = STEP-FREE / ACCESSIBLE ARRIVAL REFERENCE': 'A = 无台阶 / 无障碍到达参照', 'R = REST · S = SHADE · H = HUMAN HELP': 'R = 休息 · S = 遮荫 · H = 人工帮助', 'PROFESSIONAL ACCESSIBILITY SURVEY + REVIEW REQUIRED.': '须经专业无障碍调查与复核。', 'TWO JOURNEYS / ONE CIVIC OUTCOME': '两条路径 / 同等公共结果', 'USER A / AI-ASSISTED': '用户 A / AI 辅助', 'ARRIVAL → AI WAYFINDING → PUBLIC INTERFACE → DESTINATION → HUMAN REVIEW IF NEEDED': '到达 → AI 导航 → 公共接口 → 目的地 → 必要时人工复核', 'USER B / NO AI': '用户 B / 不使用 AI', 'ARRIVAL → STATIC SIGN → STAFFED DESK → PAPER / OFFLINE SERVICE → DESTINATION → HUMAN APPEAL': '到达 → 固定导视 → 人工服务台 → 纸质 / 离线服务 → 目的地 → 人工申诉', 'EQUIVALENT ACCESS': '等价通达', 'JZOI 90 / PILOT 01 · CIVIC WAYFINDING': 'JZOI 90 / 试点 01 · 公共导向', 'BASELINE / AI PATH / HUMAN-EQUIVALENT PATH': '基线 / AI 路径 / 人工等价路径', 'TO BE MEASURED': '待测量', 'TASK COMPLETION · WRONG TURNS · TIME · HELP REQUESTS': '任务完成 · 错误转向 · 时间 · 求助次数', 'ACCESSIBILITY FAILURE · HUMAN-EQUIVALENT COMPLETION': '无障碍失败 · 人工等价完成', 'NO BASELINE, TARGET OR ACHIEVED RESULT IS CLAIMED.': '不主张基线、目标或已实现结果。', 'CIVIC EQUIVALENCE RATE / DEFINITION': '公共等价率 / 定义', 'CAN NON-AI USERS COMPLETE THE SAME CIVIC TASK?': '非 AI 用户能否完成同一公共任务？', 'AI MARGINAL VALUE / DEFINITION': 'AI 边际价值 / 定义', 'DOES AI IMPROVE MEASURABLE OUTCOMES VS BASELINE?': '相较基线，AI 是否改善可测公共结果？', 'REVERSIBILITY / DEFINITION': '可逆性 / 定义', 'DOES SERVICE CONTINUE WHEN AI IS SWITCHED OFF?': '关闭 AI 后，服务是否仍能持续？', 'CONCEPT MEASUREMENT FRAMES · VALUES UNKNOWN / FUTURE MONITORING · PRIVACY-SAFE PROTOCOL REQUIRED BEFORE REPORTING.': '概念测量框架 · 数值未知 / 后续监测 · 报告前须建立隐私安全协议。', 'FIG-06 V3.4 · ACCESS EQUIVALENCE + BLUE-GREEN CIVIC INFRASTRUCTURE · ALL ROUTES AND ACCESSIBILITY RELATIONSHIPS REQUIRE SURVEY AND PROFESSIONAL REVIEW.': 'FIG-06 V3.4 · 通达等价 + 蓝绿公共基础设施 · 所有路径与无障碍关系均须调查及专业复核。', 'JINGZHANG OPEN INTERFACE': '京张开放接口' }));
if (lang === 'zh') { document.querySelectorAll('text').forEach(node => { const localized = zh.get(node.textContent.trim()); if (localized) node.textContent = localized; }); }
document.querySelector('svg').setAttribute('aria-label', lang === 'zh' ? '一座不用 AI 也可使用的城市：公共通达、人工等价通达与蓝绿公共基础设施' : 'A city usable without AI through public access, human-equivalent access, and blue-green civic infrastructure');
